"""Guards for the RCAEval-derived real-telemetry benchmark.

These mirror the leakage guards in `test_benchmark_dynamic_eval.py`. The
authored benchmark previously shipped the answer key as the system's own
input observation; this dataset is generated by a script, so the same
mistake could be reintroduced by a change to the generator rather than by
hand-editing data. These tests catch that.
"""

import pytest

from app.demo.rcaeval_dataset import RCAEVAL_SCENARIOS

# The generated file is produced by scripts/build_rcaeval_dataset.py and
# is not required for the rest of the suite to run.
pytestmark = pytest.mark.skipif(
    not RCAEVAL_SCENARIOS,
    reason="RCAEval scenarios not generated; run scripts/build_rcaeval_dataset.py",
)

REQUIRED_KEYS = {
    "id",
    "source_case",
    "source_system",
    "query",
    "target_service",
    "target_entity",
    "root_cause",
    "expected_tags",
    "inject_time",
    "observed_symptoms",
    "ground_truth_claims",
}


def test_scenarios_have_required_structure():
    """Every scenario must carry the same fields the evaluation pipeline
    reads off the authored benchmark, so both run through it unchanged."""
    for scenario in RCAEVAL_SCENARIOS:
        assert REQUIRED_KEYS <= set(scenario.keys()), scenario.get("id")
        assert scenario["observed_symptoms"], scenario["id"]
        assert scenario["ground_truth_claims"], scenario["id"]
        assert isinstance(scenario["inject_time"], int)


def test_no_ground_truth_leakage_into_observations():
    """The held-out answer must never appear in what the system observes.

    Checks both the composed claim sentences and the human-readable fault
    phrase (e.g. "cpu exhaustion"): raw telemetry may legitimately mention
    a metric named `checkoutservice_cpu`, but must not hand over the
    diagnosis itself."""
    for scenario in RCAEVAL_SCENARIOS:
        observed = " ".join(scenario["observed_symptoms"]).lower()
        for claim in scenario["ground_truth_claims"]:
            assert claim.lower() not in observed, (
                f"{scenario['id']}: ground-truth claim leaked into "
                f"observed_symptoms: {claim!r}"
            )
        fault_phrase = scenario["root_cause"].replace("_", " ")
        assert fault_phrase not in observed, (
            f"{scenario['id']}: root-cause phrase {fault_phrase!r} leaked "
            "into observed_symptoms"
        )


def test_observations_span_multiple_services():
    """Metric observations must cover many services, not just the faulted
    one. Emitting only the anomalous service would be leakage by
    selection: choosing what to show would itself be the answer."""
    for scenario in RCAEVAL_SCENARIOS:
        services = {
            obs.split()[1].split("_")[0]
            for obs in scenario["observed_symptoms"]
            if obs.startswith("metric ")
        }
        assert len(services) >= 3, (
            f"{scenario['id']}: metric observations name only "
            f"{len(services)} distinct service(s); expected a spread "
            "across the system"
        )


def test_stratified_across_systems_and_fault_types():
    """The subset should stay balanced; a badly skewed regeneration would
    quietly weaken every per-category result computed from it."""
    systems = [s["source_system"] for s in RCAEVAL_SCENARIOS]
    faults = [s["root_cause"] for s in RCAEVAL_SCENARIOS]
    for label, values in (("system", systems), ("fault type", faults)):
        counts = {v: values.count(v) for v in set(values)}
        spread = max(counts.values()) - min(counts.values())
        assert spread <= 2, f"{label} distribution too skewed: {counts}"
